LIST_SORT_LIMIT = 2_000_000


def list_sort_check(A_vals, A_counts, B_vals, B_counts, M, r):
    dB = len(B_vals)
    sums = []
    append = sums.append
    extend = sums.extend
    bl = bisect_left

    if max(A_counts) == 1 and max(B_counts) == 1:
        for a in A_vals:
            start = bl(B_vals, M - a)
            if start < dB:
                if start == 0:
                    extend([a + b for b in B_vals])
                else:
                    extend([a + b for b in B_vals[start:]])
    else:
        for idx_a, a in enumerate(A_vals):
            ca = A_counts[idx_a]
            start = bl(B_vals, M - a)
            if start >= dB:
                continue

            if ca == 1:
                if start == 0:
                    extend([a + b for b in B_vals])
                else:
                    extend([a + b for b in B_vals[start:]])
            else:
                for idx_b in range(start, dB):
                    cb = B_counts[idx_b]
                    w = ca if ca < cb else cb
                    if w >= r:
                        return True
                    s = a + B_vals[idx_b]
                    if w == 1:
                        append(s)
                    else:
                        extend([s] * w)

    if len(sums) < r:
        return False

    sums.sort()
    prev = sums[0]
    cnt = 1
    for x in sums[1:]:
        if x == prev:
            cnt += 1
            if cnt >= r:
                return True
        else:
            prev = x
            cnt = 1
    return cnt >= r


def match_at_least(S, A_vals, B_vals, A_counts, B_counts, r):
    i = 0
    j = len(B_vals) - 1
    total = 0
    dA = len(A_vals)

    while i < dA and j >= 0:
        s = A_vals[i] + B_vals[j]
        if s == S:
            ca = A_counts[i]
            cb = B_counts[j]
            total += ca if ca < cb else cb
            if total >= r:
                return True
            i += 1
            j -= 1
        elif s < S:
            i += 1
        else:
            j -= 1
    return False


def candidate_check(A_vals, A_counts, B_vals, B_counts, m, p, M, r):
    dA = len(A_vals)
    dB = len(B_vals)

    max_i = m if m < dA else dA - 1
    max_j = p if p < dB else dB - 1

    if (max_i + 1) * (max_j + 1) > 500_000:
        return list_sort_check(A_vals, A_counts, B_vals, B_counts, M, r)

    A_pref = A_vals[:max_i + 1]
    B_suf = B_vals[dB - 1 - max_j:dB][::-1]

    set1 = set()
    for ai in A_pref:
        for bj in B_suf:
            s = ai + bj
            if s >= M:
                set1.add(s)

    if not set1:
        return False

    contains1 = set1.__contains__
    A_suf = A_vals[dA - 1 - max_i:dA][::-1]
    B_pref = B_vals[:max_j + 1]

    cand = set()
    for ai in A_suf:
        for bj in B_pref:
            s = ai + bj
            if s >= M and contains1(s):
                cand.add(s)

    if not cand:
        return False

    del set1, contains1, A_pref, B_suf, A_suf, B_pref

    if len(cand) * (dA + dB) <= 2 * dA * dB:
        for S in cand:
            if match_at_least(S, A_vals, B_vals, A_counts, B_counts, r):
                return True
        return False

    counts = {}
    get = counts.get
    contains = cand.__contains__

    A_items = list(zip(A_vals, A_counts))
    B_items = list(zip(B_vals, B_counts))
    B_vals_local = B_vals

    for a, ca in A_items:
        if ca == 1:
            for b in B_vals_local:
                s = a + b
                if contains(s):
                    nv = get(s, 0) + 1
                    if nv >= r:
                        return True
                    counts[s] = nv
        else:
            for b, cb in B_items:
                s = a + b
                if contains(s):
                    w = ca if ca < cb else cb
                    if w >= r:
                        return True
                    nv = get(s, 0) + w
                    if nv >= r:
                        return True
                    counts[s] = nv

    return False


