                    nc = cv ^ 1
                    color[to] = nc
                    if nc == 0:
                        cnt0 += 1
                    else:
                        cnt1 += 1
                    stack.append(to)

        size = cnt0 + cnt1
        if size == 1:
            isolated += 1
        elif size & 1:
            odd_non_isolated += 1
        else:
            if (cnt0 & 1) and (cnt1 & 1):
                even_both_odd += 1

    m_parity = M & 1

