class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k <= 0 or n <= k:
            return [0] * n

        edge = {}
        count = [0]
        depth = [0]
        ord_ = ord
        alpha = 26
        get_edge = edge.get

        for w in words:
            node = 0
            for ch in w:
                c = ord_(ch) - 97
                key = node * alpha + c
                nxt = get_edge(key)
                if nxt is None:
                    nxt = len(count)
                    edge[key] = nxt
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                count[node] += 1

        base = 0
        exact = []
        kp1 = k + 1
        for node in range(1, len(count)):
            c = count[node]
            d = depth[node]
            if c >= kp1:
                if d > base:
                    base = d
            elif c == k:
                exact.append(node)

        if not exact:
            return [base] * n

        exact.sort(key=depth.__getitem__, reverse=True)
        if base >= depth[exact[0]]:
            return [base] * n

        mark = [0] * len(depth)
        ans = [base] * n

        for i, w in enumerate(words):
            token = i + 1
            node = 0
            for ch in w:
                c = ord_(ch) - 97
                node = edge[node * alpha + c]
                mark[node] = token

            for node_id in exact:
                d = depth[node_id]
                if d <= base:
                    break
                if mark[node_id] != token:
                    ans[i] = d
                    break

        return ans

