class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def count_completions(rem_odd: int, rem_even: int, next_odd: bool, left: int) -> int:
            if left == 0:
                return 1 if rem_odd == 0 and rem_even == 0 else 0

            if next_odd:
                need_odd = (left + 1) // 2
                need_even = left // 2
            else:
                need_odd = left // 2
                need_even = (left + 1) // 2

            if rem_odd != need_odd or rem_even != need_even:
                return 0

            return fact[rem_odd] * fact[rem_even]

        used = [False] * (n + 1)
        rem_odd = (n + 1) // 2
        rem_even = n // 2
        ans = []

        for pos in range(n):
            chosen = None

            for x in range(1, n + 1):
                if used[x]:
                    continue

                if x & 1:
                    no, ne = rem_odd - 1, rem_even
                else:
                    no, ne = rem_odd, rem_even - 1

                if no < 0 or ne < 0:
                    continue

                left = n - pos - 1
                next_odd = (x % 2 == 0) if left > 0 else False

                cnt = count_completions(no, ne, next_odd, left)
                if cnt == 0:
                    continue

                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            ans.append(chosen)
            used[chosen] = True

            if chosen & 1:
                rem_odd -= 1
            else:
                rem_even -= 1

        return ans

