class Solution:
    def countSubstrings(self, s: str) -> int:
        divisors = (1, 2, 3, 4, 5, 6, 7, 8, 9)

        counts = [None] * 10
        trans = [None] * 10

        for d in divisors:
            counts[d] = [0] * d
            trans[d] = [[(r * 10 + x) % d for r in range(d)] for x in range(10)]

        ans = 0

        for ch in s:
            x = ord(ch) - 48

            for d in divisors:
                cnt = counts[d]
                new = [0] * d
                tr = trans[d][x]

                for r, c in enumerate(cnt):
                    new[tr[r]] += c

                new[x % d] += 1
                counts[d] = new

            if x:
                ans += counts[x][0]

        return ans

