        full = size - 1

        # lcm for every subset of target indices
        lcms = [1] * size
        for mask in range(1, size):
            lsb = mask & -mask
            bit = lsb.bit_length() - 1
            prev = mask ^ lsb
            l = lcms[prev]
            t = target[bit]
            lcms[mask] = l // gcd(l, t) * t

        # For each subset, keep the m cheapest indices.
        candidates = [[] for _ in range(size)]
        for mask in range(1, size):
            L = lcms[mask]
            best = []
            for i, x in enumerate(nums):
                cost = (-x) % L

                if len(best) < m:
                    pos = len(best)
                    while pos > 0 and best[pos - 1][0] > cost:
                        pos -= 1
                    best.insert(pos, (cost, i))
                elif cost < best[-1][0]:
                    pos = len(best)
                    while pos > 0 and best[pos - 1][0] > cost:
                        pos -= 1
                    best.insert(pos, (cost, i))
                    best.pop()

                if len(best) == m and best[-1][0] == 0:
                    break

            candidates[mask] = best

        def gen_partitions(mask):
            if mask == 0:
                yield []
                return

            lsb = mask & -mask
            rest = mask ^ lsb

            for sub in gen_partitions(rest):
                yield [lsb] + sub
                for i in range(len(sub)):
                    yield sub[:i] + [sub[i] | lsb] + sub[i + 1:]

        ans = None

        for part in gen_partitions(full):
            part = sorted(part, key=lambda b: candidates[b][0][0] if candidates[b] else 0)
            k = len(part)

            def dfs(pos, used, total):
                nonlocal ans
                if ans is not None and total >= ans:
                    return

                if pos == k:
                    ans = total
                    return

                block = part[pos]
                for cost, idx in candidates[block]:
                    if idx not in used:
                        used.add(idx)
                        dfs(pos + 1, used, total + cost)
                        used.remove(idx)

            dfs(0, set(), 0)

        return 0 if ans is None else ans

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""
        s = [ord(ch) - 97 for ch in caption]
        INF = 10**9
        R = range(26)
        idx3 = [c * 3 for c in R]
        cost = [[abs(a - b) for b in R] for a in R]
        letters = [chr(a + 97) for a in R]

        nxt = [INF] * 78
        for c in R:
            nxt[idx3[c] + 2] = 0
        cur = [INF] * 78
        A = [0] * 26
        best = bytearray(n * 78)

        for i in range(n - 1, 0, -1):
            costs = cost[s[i]]
            for d in R:
                v = costs[d] + nxt[idx3[d]]
                if v > INF:
                    v = INF
                A[d] = v

            min1 = min(A)
            min1_char = -1
            second_min1_char = -1
            count_min1 = 0
            for d in R:
                if A[d] == min1:
                    count_min1 += 1
                    if min1_char == -1:
                        min1_char = d
                    else:
                        second_min1_char = d

            min2 = INF
            min2_char = -1
            for d in R:
                v = A[d]
                if v != min1 and v < min2:
                    min2 = v
                    min2_char = d

            base = i * 78
            for c in R:
                idx = idx3[c]
                co = costs[c]

                v = co + nxt[idx + 1]
                if v > INF:
                    v = INF
                cur[idx] = v
                best[base + idx] = c

                v = co + nxt[idx + 2]
                if v > INF:
                    v = INF
                cur[idx + 1] = v
                best[base + idx + 1] = c
                B = v

                if count_min1 == 1 and c == min1_char:
                    E = min2
                    d_excl = min2_char
                else:
                    E = min1
                    if c == min1_char:
                        d_excl = second_min1_char
                    else:
                        d_excl = min1_char

                if B <= E:
                    cur[idx + 2] = B
                    if E == B:
                        if d_excl != -1 and d_excl < c:
                            best[base + idx + 2] = d_excl
                        else:
                            best[base + idx + 2] = c
                    else:
                        best[base + idx + 2] = c
                else:
                    cur[idx + 2] = E
                    if d_excl != -1:
                        best[base + idx + 2] = d_excl
                    else:
                        best[base + idx + 2] = c

            nxt, cur = cur, nxt

        costs0 = cost[s[0]]
        ans = INF
        first = -1
        for d in R:
            v = costs0[d] + nxt[idx3[d]]
            if v > INF:
                v = INF
            if v < ans:
                ans = v
                first = d

        if ans >= INF:
            return ""

        res = [letters[first]]
        state = idx3[first]
        for i in range(1, n):
            d = best[i * 78 + state]
            res.append(letters[d])
            c = state // 3
            if d == c:
                li = state % 3
                state = idx3[d] + (2 if li == 2 else li + 1)
            else:
                state = idx3[d]

        return ''.join(res)

