        dist = [-1] * N
        q = deque([start])
        dist[start] = 0
        order = [start]
        while q:
            u = q.popleft()
            nd = dist[u] + 1
            for v, _ in adj[u]:
                if dist[v] == -1:
                    dist[v] = nd
                    q.append(v)
                    order.append(v)
        return dist, order

    distS, orderS = bfs(S)
    distT, _ = bfs(T)
    d = distS[T]

    # Count whether there are at least two distinct shortest S-T paths.
    dp = [0] * N
    dp[S] = 1
    for u in orderS:
        if dp[u] == 0:
            continue
        du = distS[u]
        if du + distT[u] != d:
            continue
        for v, _ in adj[u]:
            if distS[v] == du + 1 and du + 1 + distT[v] == d:
                if dp[v] < 2:
                    dp[v] = min(2, dp[v] + dp[u])

    if dp[T] >= 2:
        print(2 * d)
        return

    # Reconstruct the unique shortest path and mark its edges.
    is_path_edge = [False] * M
    u = S
    while u != T:
        du = distS[u]
        nxt = -1
        neid = -1
        for v, eid in adj[u]:
            if distS[v] == du + 1 and du + 1 + distT[v] == d:
                nxt = v
                neid = eid
                break
        if nxt == -1:
            print(-1)
            return
        is_path_edge[neid] = True
        u = nxt

    # Neighbors of S and T in the graph with S and T removed.
    A = [v for v, _ in adj[S] if v != T]
    B = [v for v, _ in adj[T] if v != S]

    def bfs_without_st(sources):
        dist = [-1] * N
        q = deque()
        for s in sources:
            if s != S and s != T and dist[s] == -1:
                dist[s] = 0
                q.append(s)
        while q:
            u = q.popleft()
            nd = dist[u] + 1
            for v, _ in adj[u]:
                if v != S and v != T and dist[v] == -1:
                    dist[v] = nd
                    q.append(v)
        return dist

    distA = bfs_without_st(A)
    distB = bfs_without_st(B)

    if d == 1:
        # Need a path from a neighbor of S to a neighbor of T in G \ {S, T}.
        best = -1
