        a = distA[v]
        b = distB[u]
        if a != -1 and b != -1:
            val = a + 1 + b
            if best == -1 or val < best:
                best = val

    if best == -1:
        print(-1)
    else:
        # If this equals the original internal shortest path length,
        # there were multiple shortest paths (safety check).
        if best <= d - 2:
            print(2 * d)
        else:
            print(d + 2 + best)

