from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        if n == 0:
            return []

        arr = [(r, l, w, idx) for idx, (l, r, w) in enumerate(intervals)]
        arr.sort()

        ends = [x[0] for x in arr]
        ws = [0] * n
        ids = [0] * n
        p = [0] * n

        for i, (r, l, w, idx) in enumerate(arr):
            ws[i] = w
            ids[i] = idx
            p[i] = bisect_left(ends, l, 0, i + 1)

        del arr
        del ends

        def add_idx(t, x):
            if not t:
                return (x,)
            if len(t) == 1:
                a = t[0]
                return (x, a) if x < a else (a, x)
            if len(t) == 2:
                a, b = t
                if x < a:
                    return (x, a, b)
                if x < b:
                    return (a, x, b)
                return (a, b, x)
            a, b, c = t
            if x < a:
                return (x, a, b, c)
            if x < b:
                return (a, x, b, c)
            if x < c:
                return (a, b, x, c)
            return (a, b, c, x)

        prev_w = [0] * (n + 1)
        prev_t = [()] * (n + 1)

        best_w = 0
        best_t = ()
        add = add_idx
        max_k = min(4, n)

        for k in range(1, max_k + 1):
            if prev_w[n] == -1:
                break

            cur_w = [-1] * (n + 1)
            cur_t = [None] * (n + 1)

            for i in range(1, n + 1):
                pos = i - 1
                sw = cur_w[i - 1]
                st = cur_t[i - 1]

                pp = p[pos]
                pw = prev_w[pp]

                if pw != -1:
                    tw = pw + ws[pos]

                    if tw > sw:
                        cur_w[i] = tw
                        cur_t[i] = add(prev_t[pp], ids[pos])
                        continue

                    if tw == sw and tw != -1:
                        tt = add(prev_t[pp], ids[pos])
                        if st is None or tt < st:
                            cur_w[i] = tw
                            cur_t[i] = tt
                            continue

                cur_w[i] = sw
                cur_t[i] = st

            cw = cur_w[n]
            if cw > best_w or (
                cw == best_w and cw != -1 and cur_t[n] is not None
                and (best_t is None or cur_t[n] < best_t)
            ):
                best_w = cw
                best_t = cur_t[n]

            prev_w, prev_t = cur_w, cur_t

        return list(best_t)

