class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        bits = [1 if ch == '1' else 0 for ch in s]

        def can(limit: int) -> bool:
            INF = numOps + 1

            # dp0[r] = min flips for processed prefix ending with '0'
            #          and current run length r
            # dp1[r] = same, ending with '1'
            dp0 = [INF] * (limit + 1)
            dp1 = [INF] * (limit + 1)

            b = bits[0]
            dp0[1] = b if b <= numOps else INF
            dp1[1] = 1 - b if 1 - b <= numOps else INF

            for b in bits[1:]:
                m0 = min(dp0)
                m1 = min(dp1)

                if m0 == INF and m1 == INF:
                    return False

                ndp0 = [INF] * (limit + 1)
                ndp1 = [INF] * (limit + 1)

                cost0 = b       # cost to make current bit '0'
                cost1 = 1 - b   # cost to make current bit '1'

                # Switch character: new run length becomes 1.
                if m0 < INF:
                    nv = m0 + cost1
                    if nv < ndp1[1]:
                        ndp1[1] = nv

                if m1 < INF:
                    nv = m1 + cost0
                    if nv < ndp0[1]:
                        ndp0[1] = nv

                # Keep the same character: run length increases by 1.
                for r in range(1, limit):
                    v = dp0[r]
                    if v < INF:
                        nv = v + cost0
                        if nv < ndp0[r + 1]:
                            ndp0[r + 1] = nv

                for r in range(1, limit):
                    v = dp1[r]
                    if v < INF:
                        nv = v + cost1
                        if nv < ndp1[r + 1]:
                            ndp1[r + 1] = nv

                dp0, dp1 = ndp0, ndp1

            return min(dp0) <= numOps or min(dp1) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        present = bytearray(T + 1)
        isolated = 0
        present_count = 0

        for x in nums:
            if x <= T:
                if not present[x]:
                    present[x] = 1
                    present_count += 1
            else:
                isolated += 1

        if present_count == 0:
            return isolated
        if present_count == 1 or present[1]:
            return isolated + 1

        parent = list(range(T + 1))
        size = [1] * (T + 1)
        rep = [0] * (T + 1)

        par = parent
        sz = size
        rep_arr = rep
        pres = present
        T1 = T + 1

        for d in range(1, T1):
            if not pres[d]:
                continue
            for m in range(d, T1, d):
                r = rep_arr[m]
                if r == 0:
                    rep_arr[m] = d
                else:
                    x = d
                    while par[x] != x:
                        par[x] = par[par[x]]
                        x = par[x]

                    y = r
                    while par[y] != y:
                        par[y] = par[par[y]]
                        y = par[y]

                    if x != y:
                        if sz[x] < sz[y]:
                            x, y = y, x
                        par[y] = x
                        sz[x] += sz[y]

        roots = set()
        for x in range(1, T1):
            if pres[x]:
                y = x
                while par[y] != y:
                    par[y] = par[par[y]]
                    y = par[y]
                roots.add(y)

        return len(roots) + isolated
